pub fn setlistforsell(&self, deps: DepsMut, env: Env, info: MessageInfo, islisted: bool, token_id: String, denom: String, price: u64, auto_approve: bool) -> Result<Response<C>, ContractError> {
        let mut token = self.tokens.load(deps.storage, &token_id)?;
        self.check_can_send(deps.as_ref(), &env, &info, &token)?;
        token.sell = Sell {
            islisted: Some(islisted),
            auto_approve,
            price,
            denom,
        };
        self.tokens.save(deps.storage, &token_id, &token)?;
        Ok(Response::new().add_attribute("action", "setlistforsell"))
    }

    pub fn setbidtobuy(&self, deps: DepsMut, env: Env, info: MessageInfo, token_id: String) -> Result<Response<C>, ContractError> {
        let mut token = self.tokens.load(deps.storage, &token_id)?;
        if token.sell.islisted != Some(true) {
            return Err(ContractError::Unauthorized {});
        }
        let new_bid = Bid {
            address: info.sender.to_string(),
            offer: token.sell.price.into(),
        };
        token.bids.push(new_bid);
        self.tokens.save(deps.storage, &token_id, &token)?;
        Ok(Response::new().add_attribute("action", "setbidtobuy"))
    }
